class Task:
    def __init__(self, C, S, D, T):
        self.C = C  # Worst-case execution time
        self.S = S  # Worst-case self-suspension time
        self.D = D  # Relative deadline
        self.T = T  # Period (min inter-arrival time)

    def get_absolute_deadline(self, release_time):
        return release_time + self.D

    def is_valid(self):
        return self.C > 0 and self.S > 0 and self.S < self.D and (self.C + self.S) <= self.D

def is_implicit_deadline_set(task_set):
    for task_i in task_set:
        if task_i.D != task_i.T:
            return False
    return True

def is_constrained_deadline_set(task_set):
    for task_i in task_set:
        if task_i.D > task_i.T:
            return False
    return True

class DynamicSelfSuspendingTask(Task):
    def __init__(self, C, S, D, T):
        super().__init__(C, S, D, T)
        self.current_suspension_time = 0

    def suspend(self, duration):
        if self.current_suspension_time + duration <= self.S:
            self.current_suspension_time += duration
            # Release processor
            return True
        return False # S_i violated

    def resume(self):
