class SegmentedSelfSuspendingTask(Task):
    def __init__(self, segments, D, T):
        # segments is a list of (C_j, S_j) tuples, last S_j is 0
        self.segments = segments
        C_total = sum(s[0] for s in segments)
        S_total = sum(s[1] for s in segments[:-1]) # Sum all but last S
        super().__init__(C_total, S_total, D, T)
        self.m = len(segments)

    def get_segment_pattern(self):
        return self.segments

