def calculate_R_w_j(w_j, V):
    if w_j <= V - 1:
        return 2*V + 1 + w_j
    elif w_j == V:
        return 4*V + 1
    else: # w_j > V
        floor_term = (V + 1 + w_j) // (2*V)
        return V + 1 + w_j + floor_term * V

def check_lemma_2(task_set, t_max_search):
    for t in range(1, t_max_search + 1):
        total_demand = 0
        for task_i in task_set:
            effective_deadline_offset = task_i.D - task_i.S
            num_jobs = max(0, (t - effective_deadline_offset) // task_i.T + 1)
            total_demand += num_jobs * task_i.C
        if total_demand > t:
            return False # Not schedulable
    return True # Potentially schedulable (necessary condition met)

def check_lemma_1(task_k, task_set, priority_assignment):
    hp_tasks = get_higher_priority_tasks(task_k, task_set, priority_assignment)
    for t in range(1, task_k.D + 1):
        interference = 0
        for hp_task in hp_tasks:
            interference += math.ceil(t / hp_task.T) * hp_task.C

        if task_k.C + task_k.S + interference <= t:
            return True # Necessary condition met for task_k
    return False # Task_k is not schedulable (necessary condition failed)

def check_lemma_6(M, V):
    # Assumes calculate_R_w_j(V, V) returns 4*V + 1
    total_R = 0
    for j in range(M):
        total_R += calculate_R_w_j(V, V) # w_j = V
    return total_R == M * (4*V + 1)

def check_tau_3M_plus_2_schedulability(M, V, w_values):
    total_response_time_segments = 0
    for w_j in w_values:
        total_response_time_segments += calculate_R_w_j(w_j, V)

    total_suspension_time = (M - 1) * 6 * V
    D_3M_plus_2 = M * (4*V + 1) - V + 6*V * (M - 1)

    # Original condition
    if total_response_time_segments + total_suspension_time > D_3M_plus_2:
        # Simplified condition
        if total_response_time_segments > M * (4*V + 1) - V:
            return False # Deadline missed
    return True # Deadline met

