def schedule_with_Algorithm_R(task_set_negative, current_time, processor_speed):
    tau_1 = task_set_negative.tau_1
    tau_2 = task_set_negative.tau_2

    # Assume job_1 and job_2 are current active jobs of tau_1 and tau_2
    # Assume job_1.remaining_C and job_2.remaining_C are updated
    # Assume job_2.is_suspending() is a state check

    if job_1.is_active():
        job_1_laxity = job_1.absolute_deadline - current_time - job_1.remaining_C
        if job_2.is_suspending() or job_1_laxity == 0:
